function list(){const counts={all:0,diary:0,weekly:0,note:0,trash:0};data.entries.forEach(e=>{if(e.deleted)counts.trash++;else{counts.all++;counts[e.type]++;}});Object.entries(counts).forEach(([k,v])=>$('#count-'+k).textContent=v);document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.filter===filter));const rows=data.entries.filter(e=>(filter==='trash'?e.deleted:!e.deleted&&(filter==='all'||e.type===filter))&&(!selectedDate||(e.date===selectedDate&&e.type==='diary'))&&(!tagFilter||hasTag(e.tags,tagFilter))&&`${e.title} ${plain(e.content)} ${e.tags} ${e.location||''} ${e.weather||''}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.updated.localeCompare(a.updated));$('#trash-actions').hidden=filter!=='trash';$('#empty-trash').disabled=!counts.trash;$('#total').textContent=`${rows.length} 篇`;$('#entry-list').innerHTML=rows.length?rows.map(e=>`<article class="entry ${active===e.id?'active':''}"><button class="entry-open" data-id="${escape(e.id)}"><div><span>${escape(e.date.replaceAll('-','.'))}</span><small>${labels[e.type]}</small></div><h3>${escape(e.title||'无标题')}</h3><p>${escape(plain(e.content).slice(0,80)||'还没有写下正文')}</p></button><div class="entry-tags">${displayTags(e).map(tag=>e.deleted?`<span class="entry-tag">${escape(tag)}</span>`:`<button class="entry-tag" data-browse-tag="${escape(tag)}" aria-label="筛选标签：${escape(tag)}">${escape(tag)}</button>`).join('')}</div></article>`).join(''):`<p class="no-results">${tagFilter||query?'没有匹配的记录':'这里还没有记录'}</p>`;document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>select(b.dataset.id));bindTagBrowse($('#entry-list'));renderTagFilters();renderCalendar();}

function review(){const e=current();if(!e)return;const weekly=e.type==='weekly';$('#week-range').textContent=weekly?weekDates(e.date).join(' 至 '):'';$('#week-review').hidden=!weekly;if(weekly){const [start,end]=weekDates(e.date);const records=data.entries.filter(x=>!x.deleted&&x.type==='diary'&&x.date>=start&&x.date<=end);$('#week-review').innerHTML=`<h3>这一周的日记 <small>${records.length} 篇</small></h3>${records.length?records.map(x=>`<p><time>${escape(x.date)}</time> ${escape(x.title||'无标题')}</p>`).join(''):'<p>本周暂无日记</p>'}`;}}
function select(id){document.body.classList.remove('show-trajectory');$('#trajectory-view').hidden=true;$('#trajectory').classList.remove('selected');if(current()&&$('#tags').value&&!tagComposing)commitTagDraft();hideTagSuggestions();const changed=active!==id;active=id;const e=current();$('#empty').hidden=!!e;$('#writing').hidden=!e;if(!e){$('#empty h2').textContent=selectedDate?`${selectedDate}，还没有日记`:'暂无记录';$('#first').textContent=selectedDate?'写这一天的日记':'写下第一篇';$('#breadcrumb').textContent=selectedDate?`日期空间 / ${selectedDate}`:'我的日记本';list();return;}loading=true;$('#title').value=e.title;$('#type').value=e.type;$('#date').value=e.date;loadTags(e);renderEntryPlace(e);document.querySelectorAll('[data-custom-weather]').forEach(option=>option.remove());if(e.weather&&![...$('#weather').options].some(option=>option.value===e.weather)){const option=new Option(e.weather,e.weather);option.dataset.customWeather='true';$('#weather').add(option);}$('#weather').value=e.weather||'';document.querySelectorAll('[data-custom-mood]').forEach(option=>option.remove());if(e.mood&&![...$('#mood').options].some(option=>option.value===e.mood)){const option=new Option(e.mood,e.mood);option.dataset.customMood='true';$('#mood').add(option);}$('#mood').value=e.mood||'';updateWeekday(e.date);editor.commands.setContent(e.content,{emitUpdate:false});if(changed)editor.view.updateState(EditorState.create({schema:editor.schema,doc:editor.state.doc,plugins:editor.state.plugins}));updateToolbar();$('#markdown-source').value=e.markdown??coloredMarkdown(editor.getMarkdown());$('#markdown-source').readOnly=e.deleted;applyMode();['title','type','date','location-input','weather','mood'].forEach(k=>$('#'+k).disabled=e.deleted);$('.toolbar').hidden=e.deleted||editMode!=='visual';$('#delete').hidden=e.deleted;$('#recover').hidden=!e.deleted;$('#purge-entry').hidden=!e.deleted;$('#breadcrumb').textContent=`我的日记本 / ${labels[e.type]}`;$('#word-count').textContent=`${editor.getText().replace(/\s/g,'').length} 字`;loading=false;review();list();}
function create(type='diary',title='',content='',date=selectedDate||today()){tagFilter=null;const e={id:crypto.randomUUID(),type,title:title||(type==='weekly'?'这一周，慢慢回望':''),date,tags:'',location:'',place:null,homeSnapshot:homeSnapshot(placeSettings().home),weather:'',mood:'',content:content||(type==='weekly'?'<h2>本周回顾</h2><p></p><h2>收获与感受</h2><p></p><h2>下周计划</h2><p></p>':'<p></p>'),updated:new Date().toISOString(),deleted:false};data.entries.push(e);if(selectedDate&&type!=='diary')selectedDate=null;filter=selectedDate?'diary':'all';$('.list-title h1').textContent=selectedDate?selectedDate:'全部记录';select(e.id);persist();$('#title').focus();}
