let purgeIds=[],purgeBusy=false;
function confirmTrash(ids,all=false){
 if(!ids.length)return;
 purgeIds=ids;
 $('#trash-confirm-title').textContent=all?'清空回收站？':'彻底删除这篇记录？';
 $('#trash-confirm-message').textContent=all?`将永久删除回收站中的全部 ${ids.length} 篇记录（包含搜索或筛选未显示的记录）。删除后无法在回收站恢复。`:`“${data.entries.find(e=>e.id===ids[0])?.title||'无标题'}”将永久删除，无法在回收站恢复。`;
 $('#trash-confirm-delete').textContent=all?'清空全部':'彻底删除';
 $('.trash-error').hidden=true;trashDialog.showModal();$('#trash-cancel').focus();
}
$('#purge-entry').onclick=()=>{if(current()?.deleted)confirmTrash([active]);};
