for(const [kind,label,colors] of [['text','文字颜色',[['深灰','#31463d'],['红色','#c0392b'],['橙色','#bc6b17'],['绿色','#247347'],['蓝色','#2463a8'],['紫色','#8052a0']]],['background','文字底色',[['黄色','#fff2b3'],['粉色','#f9d8df'],['浅橙','#ffe1bd'],['浅绿','#d8eddc'],['浅蓝','#d9e9ff'],['浅紫','#eadffc']]]]){
 const palette=document.createElement('div');palette.id=kind+'-color-palette';palette.className='color-palette';palette.setAttribute('popover','auto');palette.setAttribute('role','dialog');palette.setAttribute('aria-label',label);palette.innerHTML=`<h4>${label}</h4><div class="color-swatches">${colors.map(([name,color])=>`<button type="button" aria-label="${label}：${name}" data-swatch="${color}" style="--swatch:${color}"></button>`).join('')}</div><div class="color-palette-actions"><button data-clear-color>清除</button><label>自定义<input type="color" aria-label="自定义${label}" value="${colors[0][1]}"></label></div>`;document.body.append(palette);
 let selection=null;
 const trigger=$('#'+kind+'-color-button');trigger.onmousedown=event=>event.preventDefault();trigger.onclick=()=>{selection={from:editor.state.selection.from,to:editor.state.selection.to};if(palette.matches(':popover-open')){palette.hidePopover();return;}palette.showPopover();const rect=trigger.getBoundingClientRect();palette.style.left=Math.min(rect.left,window.innerWidth-240)+'px';palette.style.top=Math.min(rect.bottom+7,window.innerHeight-190)+'px';};
 const apply=value=>{if(!current()||current().deleted)return;let chain=editor.chain().focus();if(selection)chain=chain.setTextSelection(selection);if(kind==='text')value?chain.setColor(value).run():chain.unsetColor().run();else value?chain.setBackgroundColor(value).run():chain.unsetBackgroundColor().run();palette.hidePopover();};
 palette.querySelectorAll('[data-swatch]').forEach(button=>{button.onmousedown=event=>event.preventDefault();button.onclick=()=>apply(button.dataset.swatch);});palette.querySelector('[data-clear-color]').onclick=()=>apply(null);palette.querySelector('input').onchange=event=>apply(event.target.value);
}

let backupRefresh=0,backupSignature=null;
const backupType=name=>name.startsWith('before-upgrade-')?'升级前':name.startsWith('before-import-')?'导入前':name.startsWith('before-sqlite-')?'迁移前':name.startsWith('auto-')?'自动备份':'手动备份';
const backupTime=value=>new Date(value).toLocaleString('zh-CN',{hour12:false});
async function refreshBackups(){const revision=++backupRefresh;$('#backup-now').disabled=!api.createLocalBackup;$('#open-backup-folder').disabled=!api.openBackupFolder;
 if(!api.backupInfo){$('#backup-result').textContent='桌面客户端可管理本地备份';$('#backup-history').textContent='';return;}
 try{const info=await api.backupInfo();if(revision!==backupRefresh)return;const signature=JSON.stringify(info);if(signature===backupSignature)return;backupSignature=signature;$('#backup-result').dataset.state=info.last?.ok===false?'error':'saved';$('#backup-result').textContent=info.last?(info.last.ok?'最近备份成功 · ':'最近备份失败 · ')+backupTime(info.last.time)+(info.last.error?' · '+info.last.error:''):(info.files.length?'最近备份 · '+backupTime(info.files[0].time):'暂无本地备份');
 $('#backup-history').innerHTML='<h4>本地备份 <span>'+info.files.length+' 份</span></h4><p class="backup-retention">自动备份保留最近 '+info.keep+' 份</p>'+(info.files.length?info.files.map(file=>`<div class="backup-item"><div><strong>${backupType(file.name)}</strong><time>${escape(backupTime(file.time))}</time><small>${(file.size/1024).toFixed(1)} KB</small></div><button class="setting-action" data-backup-name="${escape(file.name)}" aria-label="恢复${escape(backupType(file.name))} ${escape(backupTime(file.time))}">恢复…</button></div>`).join(''):'<p>暂无备份</p>');document.querySelectorAll('[data-backup-name]').forEach(button=>button.onclick=()=>guard(async()=>{button.disabled=true;try{await saveNow();const result=await api.restoreLocalBackup(button.dataset.backupName);if(result){data=result.data;select(data.entries.find(e=>!e.deleted)?.id);$('#settings-record-count').textContent=data.entries.filter(e=>!e.deleted).length+' 篇';toast(`已导入 ${result.added} 篇，保留 ${result.conflicts} 篇冲突副本`);}}finally{button.disabled=false;await refreshBackups();}}));
 }catch(error){if(revision===backupRefresh){backupSignature=null;$('#backup-result').dataset.state='error';$('#backup-result').textContent='无法读取备份：'+error.message;$('#backup-history').textContent='';}}
}
$('#refresh-backups').onclick=refreshBackups;
$('#open-backup-folder').onclick=()=>guard(()=>api.openBackupFolder());
$('#backup-now').onclick=()=>guard(async()=>{await saveNow();$('#backup-now').disabled=true;$('#backup-result').textContent='正在备份…';try{await api.createLocalBackup();toast('本地备份已完成');}finally{await refreshBackups();}});
setInterval(()=>{if(settingsDialog.open&&!$('#settings-data').hidden)refreshBackups();},15000);
// Workspace preferences are independent of diary content and writing preferences.
let workspace={sidebar:200,entries:248,collapsed:false};try{const saved=JSON.parse(localStorage.getItem('ediary-workspace')||'{}');for(const key of ['sidebar','entries'])if(Number.isFinite(saved[key]))workspace[key]=saved[key];workspace.collapsed=saved.collapsed===true;}catch{}
function applyWorkspace(){workspace.sidebar=Math.max(190,Math.min(260,workspace.sidebar));workspace.entries=Math.max(220,Math.min(360,window.innerWidth-workspace.sidebar-510,workspace.entries));$('#app').style.setProperty('--sidebar-width',workspace.sidebar+'px');$('#app').style.setProperty('--entries-width',workspace.entries+'px');document.body.classList.toggle('list-collapsed',workspace.collapsed);$('#toggle-list').textContent=workspace.collapsed?'展开列表':'收起列表';$('#toggle-list').setAttribute('aria-expanded',String(!workspace.collapsed));document.querySelectorAll('.column-resizer').forEach(handle=>handle.setAttribute('aria-valuenow',Math.round(workspace[handle.dataset.column])));}
function saveWorkspace(){try{localStorage.setItem('ediary-workspace',JSON.stringify(workspace));}catch{}}
$('#toggle-list').onclick=()=>{workspace.collapsed=!workspace.collapsed;applyWorkspace();saveWorkspace();};
for(const [selector,key,label,min,max] of [['.sidebar','sidebar','导航宽度',190,260],['.entries','entries','列表宽度',220,360]]){const handle=document.createElement('div');handle.className='column-resizer';handle.dataset.column=key;handle.role='separator';handle.tabIndex=0;handle.setAttribute('aria-label',label);handle.setAttribute('aria-orientation','vertical');handle.setAttribute('aria-valuemin',min);handle.setAttribute('aria-valuemax',max);$(selector).append(handle);let drag=null;handle.onpointerdown=event=>{if(event.button!==0)return;drag={x:event.clientX,width:workspace[key]};handle.setPointerCapture(event.pointerId);document.body.classList.add('resizing');event.preventDefault();};handle.onpointermove=event=>{if(!drag)return;workspace[key]=drag.width+event.clientX-drag.x;applyWorkspace();};const stop=()=>{if(!drag)return;drag=null;document.body.classList.remove('resizing');saveWorkspace();};handle.onpointerup=stop;handle.onlostpointercapture=stop;handle.onpointercancel=stop;handle.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();workspace[key]=event.key==='Home'?min:event.key==='End'?max:workspace[key]+(event.key==='ArrowRight'?10:-10);applyWorkspace();saveWorkspace();};}
window.addEventListener('resize',applyWorkspace);applyWorkspace();

function hideTagSuggestions(){const popup=$('#tag-suggestions');if(popup.matches(':popover-open'))popup.hidePopover();$('#tags').setAttribute('aria-expanded','false');$('#tags').removeAttribute('aria-activedescendant');tagOption=-1;}
function bindTagBrowse(root){root.querySelectorAll('[data-browse-tag]').forEach(button=>{if(root.id==='tag-chips')button.onmousedown=event=>event.preventDefault();button.onclick=()=>browseTag(button.dataset.browseTag);});}
function renderTagChips(){const record=current();$('#tag-chips').innerHTML=tagValues.map((tag,index)=>`<span class="tag-chip" role="listitem"><button class="tag-name" data-browse-tag="${escape(tag)}" aria-label="筛选标签：${escape(tag)}">${escape(tag)}</button>${record?.deleted?'':`<button class="tag-remove" data-remove-tag="${index}" aria-label="移除标签：${escape(tag)}"><span aria-hidden="true">×</span></button>`}</span>`).join('');bindTagBrowse($('#tag-chips'));$('#tag-chips').querySelectorAll('[data-remove-tag]').forEach(button=>{button.onmousedown=event=>event.preventDefault();button.onclick=()=>{if(!current()||current().deleted)return;const removed=tagValues.splice(Number(button.dataset.removeTag),1)[0];$('#tag-feedback').textContent='已移除 '+removed;renderTagChips();syncTagDraft();$('#tags').focus();showTagSuggestions();};});}
function loadTags(record){tagOwner=record.id;tagValues=parseTags(record.tags);$('#tags').value='';$('#tags').disabled=record.deleted;$('#tag-feedback').textContent='';renderTagChips();}
function displayTags(record){return record.id===tagOwner?tagValues:parseTags(record.tags);}
function syncTagDraft(refresh=true){const record=current();if(!record||record.id!==tagOwner||record.deleted)return;const value=serializeTags([...tagValues,...parseTags($('#tags').value)]);if(record.tags===value)return;record.tags=value;record.updated=new Date().toISOString();persist();if(refresh)list();}
function commitTagDraft(value=$('#tags').value){if(!current()||current().deleted||tagComposing)return;const added=parseTags(value);if(!added.length){$('#tags').value='';hideTagSuggestions();return;}const previous=tagValues.length;tagValues=parseTags([...tagValues,...added].join(','));$('#tags').value='';syncTagDraft(false);renderTagChips();list();$('#tag-feedback').textContent=tagValues.length===previous?'标签已存在':'已添加 '+added.join('、');hideTagSuggestions();}
function selectTagOption(index){tagOption=index;$('#tag-suggestions').querySelectorAll('[role=option]').forEach((option,i)=>option.setAttribute('aria-selected',String(i===index)));if(index>=0){$('#tags').setAttribute('aria-activedescendant','tag-option-'+index);$('#tag-option-'+index)?.scrollIntoView({block:'nearest'});}else $('#tags').removeAttribute('aria-activedescendant');}
function showTagSuggestions(){if(!current()||current().deleted||tagComposing)return;tagOptions=suggestTags(data.entries.filter(e=>e.id!==tagOwner),tagValues,$('#tags').value);tagOption=-1;const popup=$('#tag-suggestions');if(!tagOptions.length){hideTagSuggestions();return;}popup.innerHTML=tagOptions.map((item,index)=>`<button type="button" role="option" aria-selected="false" tabindex="-1" id="tag-option-${index}" data-tag-option="${index}"><span>${escape(item.name)}</span><small>${item.count} 篇</small></button>`).join('');const rect=$('#tags').getBoundingClientRect();popup.style.left=Math.max(12,Math.min(rect.left,window.innerWidth-276))+'px';popup.style.top=(rect.bottom+6)+'px';popup.style.maxHeight=Math.max(80,Math.min(240,window.innerHeight-rect.bottom-18))+'px';if(!popup.matches(':popover-open'))popup.showPopover();$('#tags').setAttribute('aria-expanded','true');popup.querySelectorAll('[data-tag-option]').forEach(button=>{button.onmousedown=event=>event.preventDefault();button.onclick=()=>{commitTagDraft(tagOptions[Number(button.dataset.tagOption)].name);$('#tags').focus();};});}
function tagInput(event){if(event?.isComposing||tagComposing)return;const input=$('#tags');const {confirmed,draft}=splitTagDraft(input.value);if(draft!==input.value){tagValues=parseTags([...tagValues,...confirmed].join(','));input.value=draft;renderTagChips();}syncTagDraft(false);list();showTagSuggestions();}

$('#tags').addEventListener('compositionstart',()=>{tagComposing=true;hideTagSuggestions();});$('#tags').addEventListener('compositionend',()=>{tagComposing=false;tagInput();});$('#tags').addEventListener('input',tagInput);$('#tags').addEventListener('focus',showTagSuggestions);$('#tags').addEventListener('blur',()=>{commitTagDraft();hideTagSuggestions();});
$('#tags').addEventListener('keydown',event=>{if(event.isComposing||tagComposing||event.keyCode===229)return;if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();if(!$('#tag-suggestions').matches(':popover-open'))showTagSuggestions();if(tagOptions.length)selectTagOption(event.key==='ArrowDown'?(tagOption+1)%tagOptions.length:(tagOption<=0?tagOptions.length-1:tagOption-1));}else if(event.key==='Enter'){event.preventDefault();commitTagDraft(tagOption>=0?tagOptions[tagOption].name:$('#tags').value);}else if(event.key==='Escape'){event.preventDefault();event.stopPropagation();hideTagSuggestions();}else if(event.key==='Backspace'&&!$('#tags').value){[...$('#tag-chips').querySelectorAll('.tag-remove')].at(-1)?.focus();}});
$('#tags').addEventListener('paste',event=>{const text=event.clipboardData.getData('text');if(!hasTagSeparator(text))return;event.preventDefault();const input=$('#tags');commitTagDraft(input.value.slice(0,input.selectionStart)+text+input.value.slice(input.selectionEnd));showTagSuggestions();});

document.addEventListener('pointerdown',event=>{if(!event.target.closest('.tag-editor,#tag-suggestions'))hideTagSuggestions();});window.addEventListener('resize',hideTagSuggestions);
function renderTagFilters(){const catalog=tagCatalog(data.entries.map(entry=>entry.id===tagOwner?{...entry,tags:serializeTags(tagValues)}:entry));$('#tag-filter-toggle').textContent='标签'+(catalog.length?' · '+catalog.length:'');$('#active-tag-filter').hidden=!tagFilter;if(tagFilter){$('#active-tag-filter').textContent=tagFilter+' ×';$('#active-tag-filter').setAttribute('aria-label','清除标签筛选：'+tagFilter);}$('#tag-filter-panel').innerHTML=catalog.length?catalog.map(item=>`<button data-browse-tag="${escape(item.name)}" aria-pressed="${!!tagFilter&&tagKey(tagFilter)===tagKey(item.name)}"><span>${escape(item.name)}</span><small>${item.count}</small></button>`).join(''):'<p>暂无标签</p>';bindTagBrowse($('#tag-filter-panel'));}
function browseTag(tag){tagFilter=tag;selectedDate=null;query='';$('#search').value='';filter='all';$('.list-title h1').textContent='全部记录';$('#tag-filter-panel').hidden=true;$('#tag-filter-toggle').setAttribute('aria-expanded','false');hideTagSuggestions();const match=data.entries.filter(e=>!e.deleted&&hasTag(e.tags,tag)).sort((a,b)=>b.date.localeCompare(a.date)||b.updated.localeCompare(a.updated));select(match.some(e=>e.id===active)?active:match[0]?.id);if(workspace.collapsed){workspace.collapsed=false;applyWorkspace();saveWorkspace();}}
$('#tag-filter-toggle').onclick=()=>{const panel=$('#tag-filter-panel');panel.hidden=!panel.hidden;$('#tag-filter-toggle').setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)renderTagFilters();};
$('#active-tag-filter').onclick=()=>{tagFilter=null;list();};


function placeSettings(){return data.places||emptyPlaces();}
function renderEntryPlace(entry){
 $('#location-input').textContent=entry.place?placeLabel(entry.place):entry.location||'选择地点';
 $('#location-input').title=entry.place?placeLabel(entry.place):entry.location||'选择地点';
 $('#entry-home').textContent='归属地：'+(placeLabel(entry.homeSnapshot)||'未设置');$('#entry-home').disabled=entry.deleted;
 const local=isLocal(entry.place,entry.homeSnapshot);$('#entry-local-state').textContent=local===null?'':local?'本地':'外地';$('#entry-local-state').dataset.local=String(local);
}
function renderPlaceSettings(){
 $('#configure-home').textContent=placeLabel(placeSettings().home)||'选择归属地';
 $('#settings-favorites').innerHTML=placeSettings().favorites.length?placeSettings().favorites.map((place,index)=>`<div class="favorite-setting"><span>${escape(placeLabel(place))}</span><button data-remove-favorite="${index}" aria-label="取消收藏：${escape(placeLabel(place))}">取消收藏</button></div>`).join(''):'<p class="muted">暂无收藏</p>';
 $('#settings-favorites').querySelectorAll('[data-remove-favorite]').forEach(button=>button.onclick=()=>guard(()=>savePlaceSettings({...placeSettings(),favorites:placeSettings().favorites.filter((_,index)=>index!==Number(button.dataset.removeFavorite))})));
}
async function savePlaceSettings(value){data.places=validatePlaces(value);persist();renderPlaceSettings();$('#places-status').textContent='正在保存…';try{await saveNow();$('#places-status').textContent='已保存';}catch(error){$('#places-status').textContent='保存失败';throw error;}}
const placePicker=createPlacePicker({getSettings:placeSettings,onFavorites:favorites=>savePlaceSettings({...placeSettings(),favorites})});
$('#location-input').onclick=()=>{const entry=current();if(!entry||entry.deleted)return;placePicker.open({title:'日记地点',value:entry.place||placeSettings().home,onSelect:value=>{if(current()?.id!==entry.id)throw Error('记录已切换，请重新选择');entry.place=value;entry.location=placeLabel(value);if(entry.homeSnapshot===undefined)entry.homeSnapshot=null;entry.updated=new Date().toISOString();persist();renderEntryPlace(entry);list();}});};
$('#entry-home').onclick=()=>{const entry=current();if(!entry||entry.deleted)return;placePicker.open({title:'本篇归属地',value:entry.homeSnapshot,onSelect:value=>{if(current()?.id!==entry.id)throw Error('记录已切换，请重新选择');entry.homeSnapshot=homeSnapshot(value);entry.updated=new Date().toISOString();persist();renderEntryPlace(entry);}});};
$('#configure-home').onclick=()=>placePicker.open({title:'我的归属地',value:placeSettings().home,onSelect:home=>savePlaceSettings({...placeSettings(),home})});
$('#add-favorite').onclick=()=>placePicker.open({title:'收藏常用地点',value:placeSettings().home,onSelect:place=>{if(!place)return;if(placeSettings().favorites.some(item=>placeKey(item)===placeKey(place)))return;return savePlaceSettings({...placeSettings(),favorites:[...placeSettings().favorites,place]});}});
const trajectoryView=createTrajectoryView({host:trajectoryHost,getEntries:()=>data.entries,openEntry:id=>{selectedDate=null;tagFilter=null;query='';$('#search').value='';filter='all';$('.list-title h1').textContent='全部记录';select(id);}});
$('#trajectory').onclick=()=>guard(async()=>{if(!libraryLoaded)return;if(current()&&$('#tags').value&&!tagComposing)commitTagDraft();hideTagSuggestions();document.body.classList.remove('focused');$('#focus').textContent='专注写作';document.body.classList.add('show-trajectory');trajectoryHost.hidden=false;document.querySelectorAll('[data-filter]').forEach(button=>button.classList.remove('selected'));$('#trajectory').classList.add('selected');await trajectoryView.open();});
